sys_ws_operation.operation_script:
(function process(request, response) {
    var orderSysId = request.queryParams.order_sys_id ?
        request.queryParams.order_sys_id.toString() : '';

    if (!orderSysId) {
        response.setStatus(400);
        response.setBody({
            result: { success: false, error: 'order_sys_id query parameter is required' }
        });
        return;
    }

    try {
        var sim = new x_2056099_indust_0.WarehouseSimulator();
        var result = sim.simulateFromOrder(orderSysId);
        response.setStatus(200);
        response.setBody({ result: result });
    } catch (e) {
        response.setStatus(500);
        response.setBody({
            result: { success: false, error: 'Simulation error: ' + e.message }
        });
    }
})(request, response);
